const japanLawLandscape={src:"assets/diagrams/postwar-japanese-constitutional-order.svg",alt:"Diagram of constitutional and legal authority in postwar Imperial Japan",caption:"The Emperor remains the constitutional apex while Cabinet, Diet, courts, ministries, local government, and household registers exercise distinct forms of authority"};
